mapper.select:
/* BmsPkgNoMapper.checkDupPkgByPackingNo : 박스번호 중복 조회 */
SELECT 
	COUNT(*) AS CNT
FROM TB_BMS_IN_PLAN_PKG PKG 
WHERE PACKING_NO = #{packingNo}
AND DELETE_YN = 'N'

/* BmsPkgNoMapper.selectInPlanWithPkgByMblWithBl : 해당 BL 박스 리스트  */
SELECT 
	   _plan.IN_PLAN_NO
	 , _plan.BL_NO
	 , _plan.MBL_NO
	 , _plan.CARGO_REFERENCE_NO
	 , _plan.EX_CT
FROM TB_BMS_IN_PLAN _plan WITH (NOLOCK)
INNER JOIN TB_BMS_IN _in WITH (NOLOCK)
	ON _in.IN_PLAN_NO = _plan.IN_PLAN_NO
WHERE  _in.IN_PLAN_NO = #{inPlanNo}
	AND _plan.MBL_NO = #{mblNo}
	AND _plan.BL_NO = #{blNo}

/* BmsPkgNoMapper.selectBmsInByInNo : 반입번호로 반입 조회 */
SELECT 
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE IN_NO = #{inNo}

/* BmsPkgNoMapper.selectOriginBlByInNo : 입항 반입의 데이터를 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
	AND BL_NO = #{blNo}
	AND IN_PLAN_NO > 0
ORDER BY CARRYIN_DATE DESC

/* BmsPkgNoMapper.selectOriginBlByInNoClass : 반입유형으로 데이터를 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
	AND BL_NO = #{blNo}
	AND IN_CLASS = #{inClass}
ORDER BY CARRYIN_DATE DESC

/* BmsPkgNoMapper.selectBmsInPlanByInPlanNo : 반입예정번호로 반입예정 조회 */
SELECT 
	*
FROM TB_BMS_IN_PLAN WITH (NOLOCK)
WHERE IN_PLAN_NO = #{inPlanNo}

/* BmsPkgNoMapper.selectPkgListByInPlanNo : 반입예정번호로 박스 리스트 조회 */
SELECT 
	*
FROM TB_BMS_IN_PLAN_PKG 
WHERE IN_PLAN_NO = #{inPlanNo}
	AND DELETE_YN = 'N'

/* BmsPkgNoMapper.sumPkgByInPlanNo : 반입예정번호로 박스 카운트 */
SELECT 
	SUM(PACKING_CT) AS sum
FROM TB_BMS_IN_PLAN_PKG 
WHERE IN_PLAN_NO = #{inPlanNo}
	AND DELETE_YN = 'N'

mapper.insert:
/* BmsPkgNoMapper.insertPkg : 박스저장 */
INSERT INTO TB_BMS_IN_PLAN_PKG (
	  IN_PLAN_NO
	, BL_NO
	, PACKING_NO
	, PACKING_CT
	, IN_CT
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
	, UPDATE_USER_ID
	, UPDATE_DATE_TIME
)
VALUES(
	  #{inPlanNo}
	, #{blNo}
	, #{packingNo}
	, 1
	, #{inCt}
	, #{updateUserId}
	, GETDATE()
	, #{updateUserId}
	, GETDATE()
)

mapper.update:
/* BmsPkgNoMapper.softDeleteInPlanPkg */
UPDATE TB_BMS_IN_PLAN_PKG 
SET 
	DELETE_YN = 'Y'
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE IN_PLAN_NO = #{inPlanNo}

/* BmsPkgNoMapper.updatePkgNewCargoNo */
UPDATE TB_BMS_IN_PLAN_PKG 
SET 
	NEW_CARGO_REFERENCE_NO = #{newCargoReferenceNo}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE SEQ IN (#{item.seq})

/* BmsPkgNoMapper.updateBlankNewCargoNoFromPkg */
UPDATE TB_BMS_IN_PLAN_PKG 
SET 
	NEW_CARGO_REFERENCE_NO = ''
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE IN_PLAN_NO = #{inPlanNo}
	AND BL_NO = #{blNo}
	AND NEW_CARGO_REFERENCE_NO = #{newCargoReferenceNo}

mapper.select:
/* BmsPkgNoMapper.selectInPlanNoByCargoWithBl : 생성한 IN_PLAN_NO 조회  */
SELECT TOP 1
	IN_PLAN_NO
FROM TB_BMS_IN_PLAN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
AND BL_NO = #{blNo}
ORDER BY IN_PLAN_NO DESC

