/* BmsPkgNoMapper.updateInPlanNo */
UPDATE TB_BMS_IN 
SET 
	IN_PLAN_NO = #{inPlanNo}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE IN_NO = #{inNo}

/* BmsPkgNoMapper.updateOrigInPlanNo */
UPDATE TB_BMS_IN 
SET 
	ORIG_IN_PLAN_NO = #{origInPlanNo}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE IN_NO = #{inNo}

mapper.select:
/* BmsPkgNoMapper.selectXrayHistoryByInPlanNo : Xray History 데이터 존재유무 조회  */
SELECT COUNT(*) AS CNT
FROM TB_BMS_XRAY_HISTORY WITH (NOLOCK)
WHERE IN_PLAN_NO = #{inPlanNo}
AND PACKING_NO = #{packingNo}

/* BmsPkgNoMapper.selectXrayResultByInPlanNo : Xray Result 데이터 존재유무 조회  */
SELECT COUNT(*) AS CNT
FROM TB_BMS_XRAY_RESULT WITH (NOLOCK)
WHERE IN_PLAN_NO = #{inPlanNo}

