/* BmsPkgNoMapper.softDeleteInPlanPkgByPkgNo */
UPDATE TB_BMS_IN_PLAN_PKG 
SET 
	DELETE_YN = 'Y'
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE PACKING_NO = #{packingNo}

/* BmsPkgNoMapper.updateXrayHistory : Xray History 박스변경 */
UPDATE TB_BMS_XRAY_HISTORY SET
	PACKING_NO = #{packingNo}
WHERE IN_PLAN_NO = #{inPlanNo}
AND PACKING_NO = #{oldPackingNo}

/* BmsPkgNoMapper.updatePkg : 박스변경 */
UPDATE TB_BMS_IN_PLAN_PKG SET
	PACKING_NO = #{packingNo}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE SEQ = #{seq}

mapper.select:
/* BmsPkgNoMapper.checkDupPkgByInPackingNo : 한 inplanNo 박스번호 중복 조회 */
SELECT 
	COUNT(*) AS CNT
FROM TB_BMS_IN_PLAN_PKG PKG 
WHERE PACKING_NO = #{packingNo}
AND DELETE_YN = 'N'
AND IN_PLAN_NO = #{inPlanNo}

/* BmsPkgNoMapper.checkDupPkgInfoByPackingNo : 한 inplanNo 박스번호 중복 조회 */
SELECT 
	COUNT(*) AS CNT
	,MAX(PKG.BL_NO) AS BL_NO
	,MAX(I.IN_CLASS) AS IN_CLASS
FROM TB_BMS_IN_PLAN_PKG PKG 
LEFT JOIN TB_BMS_IN I ON I.IN_PLAN_NO = PKG.IN_PLAN_NO
WHERE PKG.PACKING_NO = #{packingNo}
AND PKG.DELETE_YN = 'N'
AND PKG.IN_PLAN_NO != #{inPlanNo}

/* BmsPkgNoMapper.checkBoxOutScanByPackingNo : 출고스캔 데이터 조회 */
SELECT
	COUNT(*) AS CNT
FROM TB_BMS_OUT_SCAN 
WHERE SCAN_NO = #{packingNo}
AND SCAN_RESULT = '완료'

/* BmsPkgNoMapper.checkBoxDeliveryOutScanByPackingNo : 박스스캔 데이터 조회 */
SELECT
	COUNT(*) AS CNT
FROM TB_BMS_OUT_DELIVERY
WHERE PACKING_NO = #{packingNo}

mapper.update:
/* BmsPkgNoMapper.updatePantosPkgNo : 판토스 박스변경 */
BEGIN

UPDATE TB_BMS_LOCATION_SCAN SET
	SCAN_NO = #{packingNo}
WHERE BL_NO = #{blNo}
AND SCAN_NO = #{oldPackingNo};

UPDATE TB_BMS_STOCK_PKG_SCAN SET
	SCAN_NO = #{packingNo}
	,PACKING_NO = #{packingNo}
WHERE BL_NO = #{blNo}
AND SCAN_NO = #{oldPackingNo};

UPDATE TB_BMS_OUT_SCAN SET
	SCAN_NO = #{packingNo}
WHERE BL_NO = #{blNo}
AND SCAN_NO = #{oldPackingNo};

UPDATE TB_BMS_TIC_MOVE_SCAN SET
	SCAN_NO = #{packingNo}
WHERE BL_NO = #{blNo}
AND SCAN_NO = #{oldPackingNo};

END
